<h1 class="h3">Agenda de visitas</h1><p class="text-muted">Programa una visita desde CRM → Gestionar consulta → Programar visita. Fechas y horas de Lima.</p>
<form class="card card-body mb-4" action="<?= BASE_URL ?>/visits" method="get"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="fecha">Día</label><input class="form-control" id="fecha" name="fecha" type="date" value="<?= e($day) ?>"></div><div class="col-md-4"><label class="form-label" for="estado">Estado</label><select class="form-select" id="estado" name="estado"><option value="">Todos</option><?php foreach (Visit::STATES as $value=>$label): ?><option value="<?= e($value) ?>" <?= $state===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-md-4 d-flex gap-2 align-items-end"><button class="btn btn-primary">Filtrar</button><a class="btn btn-outline-secondary" href="<?= BASE_URL ?>/visits">Limpiar</a></div></div></form>
<?php if (!$visits): ?><div class="card card-body text-center py-5"><h2 class="h5">No hay visitas para mostrar</h2><a href="<?= BASE_URL ?>/crm">Ir al CRM para programar una visita</a></div><?php else: ?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th scope="col">N.º</th><th>Fecha y hora</th><th>Cliente / Inmueble</th><th>Vendedor</th><th>Modalidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php $rowNumber = 0; foreach ($visits as $item): ?><tr><th scope="row" class="text-muted text-center"><?= ++$rowNumber ?></th><td><?= e($item['fecha_hora']) ?></td><td><?= e($item['cliente']) ?><div class="text-muted small"><?= e($item['titulo']) ?></div></td><td><?= e($item['vendedor'] ?? 'Sin asignar') ?></td><td><?= e(Visit::MODES[$item['modalidad']]) ?></td><td><span class="badge text-bg-info"><?= e(Visit::STATES[$item['estado_visita']]) ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/visits/edit?id=<?= (int)$item['id'] ?>">Gestionar</a></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted mt-2">Hasta 100 visitas, ordenadas de fecha más reciente a más antigua. Los vendedores solo ven las visitas a su nombre.</p><?php endif; ?>
